head.script:
scwin.trigger1_onclick = function(e) {
    checkcombobox1.setDisplayAllOptionLabel(true);
};
scwin.trigger2_onclick = function(e) {
    checkcombobox1.setDisplayAllOptionLabel(false);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 checkcombobox1 의 displayAllOptionLabel 부분을 확인한다.
    //1. In the Source tab, check the displayAllOptionLabel portion of checkcombobox1.
    //Verify step 1. displayAllOptionLabel="false"
    //1. displayAllOptionLabel = "false"
    //Test step 2. allOption 부분을 확인한다.
    //2. Check the allOption part.
    //Verify step 2. allOption="true"
    //2. allOption = "true"
    //Test step 3. 브라우저에서 전체 체크를 한다.
    //3. Make a full check in your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_0_checkbox').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_label').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 체크콤보박스가 전체 체크되면서, 1 2 3 4 로 표현된다.
    //3. The check combo box is checked as a whole and is represented by 1 2 3 4.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_label').innerText", "1 2 3 4");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. setDisplayAllOptionLabel(true) 버튼을 클릭한다.
    //4. Click the setDisplayAllOptionLabel (true) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 4. 전체선택으로 표현된다.(1 2 3 4 -> 전체선택)
    //4. It is represented as a whole selection (1 2 3 4 -> select all)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_label').innerText == '전체선택'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. setDisplayAllOptionLabel(false) 버튼을 클릭한다.
    //5. Click the setDisplayAllOptionLabel (false) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 5. 다시 1 2 3 4 로 표현된다. (전체선택 -> 1 2 3 4)
    //5. It is expressed as 1 2 3 4 again. (Select All -> 1 2 3 4)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_label').innerText", "1 2 3 4");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 26-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
